// Personas: the real customers the product is for, and the missions the
// tester kobold goes on as one of them (persona tests). It owns the
// `personas` and `tests` records and offers them through its plugs
// (`personas`, `missions`); what a mission finds goes to Signals' plug, and
// a mission on a prototype runs where Explorations' plug (`ideas`) says.
import { defineExtension } from "@software-factory/core";
import { asked } from "../../asked.js";
import { kept } from "../../kobble/records.js";
import { Refused } from "../../refused.js";
import { addPersona } from "./actions.js";
import { MissionIdeas } from "./mission-ideas.js";
import { PersonaTests } from "./persona-tests.js";
import { personasPlug as supportPlug } from "./support.js";
import { missionsNow, personaPage, personasView, testPage, testsOf, } from "./views.js";
export const extension = defineExtension({
    id: "personas",
    name: "Personas",
    about: "Made-up customers who try the app.",
    core: true,
    needs: ["signals"],
    brings: { pages: ["personas"], kobolds: ["tester"] },
});
// The personas, as other extensions reach them.
export function personasOffer(store) {
    return {
        all: () => store().all("personas"),
        get: (id) => store().get("personas", id),
        add: (persona) => addPersona(store(), persona),
    };
}
// The missions, as other extensions reach them.
export function missionsOffer(store, tests) {
    return {
        of: (ids) => store()
            .all("tests")
            .filter((test) => ids.includes(test.id)),
        now: () => missionsNow(store()),
        start: (mission) => tests.start(mission),
    };
}
export function serve(host) {
    const tests = new PersonaTests({
        claude: host.claude,
        cwd: host.project,
        store: host.store,
        signals: () => host.plug("signals"),
        app: (test) => test.on === "main"
            ? host.app(test.product ?? null)
            : prototype(host, test.on, test.persona),
        browser: host.browser,
        onChange: () => {
            host.changed("tests");
        },
    });
    const ideas = new MissionIdeas({
        claude: host.claude,
        cwd: host.project,
        store: host.store,
        apps: host.apps,
    });
    return {
        routes: {
            ...personaRoutes(host),
            ...missionRoutes(host, tests, ideas),
        },
        offers: {
            personas: personasOffer(host.store),
            missions: missionsOffer(host.store, tests),
        },
        support: () => supportPlug({ store: host.store, tests, changed: host.changed }),
        // Missions that were running when the factory stopped.
        start: () => {
            if (host.records())
                tests.recover();
        },
    };
}
// A mission on a prototype runs where Explorations opens it.
function prototype(host, on, persona) {
    const ideas = host.plug("ideas");
    if (!ideas)
        throw new Refused("Explorations is not installed, so there is no prototype to test.");
    return ideas.prototype(on, persona);
}
// The personas, one persona, and New persona.
function personaRoutes(host) {
    const signals = () => host.plug("signals")?.all() ?? [];
    return {
        "GET /api/kobble/personas": () => kept(() => personasView(host.store(), signals())),
        "GET /api/kobble/persona": (_body, url) => kept(() => personaPage(host.store(), asked(url, "id", "persona"), signals())),
        "POST /api/kobble/personas": async (body) => {
            const answer = await kept(() => ({
                persona: addPersona(host.store(), body),
            }));
            host.changed("personas");
            return answer;
        },
    };
}
// Persona tests (missions): the one the kobold suggests, start one, a
// persona's tests, one test.
function missionRoutes(host, tests, ideas) {
    return {
        "GET /api/kobble/mission": (_body, url) => kept(async () => ({
            mission: await ideas.suggest(asked(url, "persona", "persona"), url.searchParams.get("again") === "yes"),
        })),
        "GET /api/kobble/tests": (_body, url) => kept(() => ({
            tests: testsOf(host.store(), asked(url, "persona", "persona")),
        })),
        "GET /api/kobble/test": (_body, url) => kept(() => testPage(host.store(), asked(url, "id", "test"), host.plug("signals")?.all() ?? [])),
        "POST /api/kobble/tests": (body) => kept(() => {
            const test = tests.start(body);
            ideas.forget(test.persona);
            return { test };
        }),
    };
}
